if(!K.fix42b){ K.fix42b = true;              /* heal the runaway-counter saves */
  if(K.wave > 4){ K.wave = 3; K.cleared = Math.min(K.cleared, 2); K.choiceAt = 5; K.supp = 0; K.held = false; } }

